item.aggregated_output:
  1	import {createHash} from "node:crypto";
  2	
  3	import {aggregateDebtViews, buildDebtServiceSchedule, calculateAllInCost, calculateCovenantHeadroom, calculateLeverage, calculateLiquidityCoverage, calculateProFormaPosition, maturityConcentration} from "@offroad/financial-core";
  4	import Decimal from "decimal.js";
  5	import {z} from "zod";
  6	
  7	/**
  8	 * Executor of the method `compare-refinancing-before-after` (v5, after the third independent
  9	 * review). Every alternative is shown before and after with the same objects: gross and net debt by
 10	 * the contractual components, leverage on a declared EBITDA, headroom only against a resolved and
 11	 * comparable limit, concentration by the schedule's own periods (safra years with their end dates,
 12	 * new principal placed by date), principal cover per period when cash generation is declared, and
 13	 * the all-in cost of the new debt including exit premiums and fees paid from cash. The cost of the
 14	 * existing debt is a different basis and is never ranked against the new debt's all-in. A retired
 15	 * series without a priced exit blocks its alternative; a ranking needs a declared discriminator.
 16	 */
 17	const nonNegative = z.string().regex(/^\d+(\.\d+)?$/);
 18	const rate = z.string().regex(/^\d+(\.\d+)?$/);
 19	const nonEmpty = z.string().trim().min(1);
 20	/** A calendar date that exists: the regex alone would let 2026-02-30 through. */
 21	const isoDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/).refine((value) => { const [year, month, day] = value.split("-").map(Number) as [number, number, number]; const date = new Date(Date.UTC(year, month - 1, day)); return date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day; }, {message: "not a calendar date"});
 22	const unitSchema = z.enum(["BRL", "BRL thousand", "BRL million", "USD", "USD thousand"]);
 23	const anchorSchema = z.object({document: nonEmpty, page: z.number().int().positive().optional(), note: nonEmpty.optional(), clause: nonEmpty.optional()}).strict();
 24	type Anchor = z.infer<typeof anchorSchema>;
 25	const compare = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
 26	
 27	export const alternativeSchema = z.object({
 28	  id: z.string().regex(/^[a-z][a-z0-9_-]*$/),
 29	  label: nonEmpty,
 30	  newDebt: z.object({amount: nonNegative, annualRate: rate, termMonths: z.number().int().positive(), graceMonths: z.number().int().nonnegative(), format: z.enum(["sac", "price", "bullet", "balloon"]), upfrontFeeRate: rate, disbursementDate: isoDate, origin: nonEmpty, anchor: anchorSchema}).strict().nullable(),
 31	  /** Series retired, each with its principal anchored to the ledger, its priced exit (from the exit-cost executor) and the anchor of its maturity; a null price blocks the alternative. */
 32	  retired: z.array(z.object({seriesId: nonEmpty, principal: z.object({value: nonNegative, anchor: anchorSchema}).strict(), exitPremium: z.object({value: nonNegative, anchor: anchorSchema}).strict().nullable(), maturityPeriod: nonEmpty, maturityAnchor: anchorSchema}).strict()).default([]),
 33	  /** Other cash costs of the alternative (advisory, registry), an explicit zero included; null means the base does not state them and the all-in is not computed. */
 34	  feesPaidFromCash: z.object({value: nonNegative, anchor: anchorSchema}).strict().nullable().default(null),
 35	  /** Terms the alternative still lacks; carried, never filled. */
 36	  uncoveredTerms: z.array(nonEmpty).default([]),
 37	}).strict();
 38	
 39	const UNIT_WORDS: Record<z.infer<typeof unitSchema>, RegExp> = {"BRL": /\b(R\$|reais|BRL)\b(?!\s*(mil|milh))/i, "BRL thousand": /\b(mil|thousand)\b/i, "BRL million": /\b(milh[õo]es|million)\b/i, "USD": /\bUSD\b(?!\s*(mil|thousand))/i, "USD thousand": /\bUSD\b.*\b(mil|thousand)\b/i};
 40	
 41	export const beforeAfterInputSchema = z.object({
 42	  referenceDate: isoDate,
 43	  unit: unitSchema,
 44	  /** Where the source states the unit; its note must name that unit, so a relabelled scale is refused. */
 45	  unitAnchor: anchorSchema.extend({note: nonEmpty}),
 46	  before: z.object({
 47	    grossDebt: z.object({value: nonNegative, anchor: anchorSchema}).strict(),
 48	    unrestrictedCash: z.object({value: nonNegative, anchor: anchorSchema}).strict(),
 49	    derivativeLiabilities: z.object({value: nonNegative, anchor: anchorSchema}).strict(),
 50	    derivativeAssets: z.object({value: nonNegative, anchor: anchorSchema}).strict(),
 51	    /** Twelve months by dates, so an annualized quarter cannot pose as LTM. */
 52	    ltmEbitda: z.object({value: nonNegative, periodStart: isoDate, periodEnd: isoDate, definitionKey: nonEmpty, basis: z.enum(["company_opened", "implied_from_reported_index", "derived_proxy"]), anchor: anchorSchema}).strict().nullable(),
 53	    /** The schedule in the ledger's own periods; `endsAt` places new principal by date, null marks the open-ended bucket. */
 54	    schedule: z.array(z.object({period: nonEmpty, amount: z.string().regex(/^-?\d+(\.\d+)?$/), endsAt: isoDate.nullable(), kind: z.enum(["maturity", "adjustment"]).default("maturity")}).strict()).min(1),
 55	    /** Cost of the existing debt, on its own basis; never the same basis as a new debt's all-in. */
 56	    costOfExistingDebt: z.object({weightedAverageRate: rate, basis: nonEmpty, anchor: anchorSchema}).strict(),
 57	    /** Cash generation per period when the base declares it; without it the cover per period is insufficient evidence. */
 58	    cfadsByPeriod: z.record(nonEmpty, nonNegative).nullable().default(null),
 59	  }).strict(),
 60	  covenant: z.object({
 61	    instrument: nonEmpty,
 62	    limit: rate,
 63	    direction: z.enum(["maximum", "minimum"]),
 64	    /** When the indenture measures the index; a reading at the reference date is interim unless it is a measurement date. */
 65	    measurement: z.object({frequency: z.enum(["annual", "semiannual", "quarterly"]), nextDate: isoDate}).strict(),
 66	    /** The tier the limit belongs to: applicable when its condition is proven, conditional while the proof is missing, not applicable when ruled out. */
 67	    tier: z.object({applicability: z.enum(["applicable", "conditional", "not_applicable"]), condition: nonEmpty}).strict().nullable(),
 68	    state: z.enum(["resolved", "insufficient_evidence"]),
 69	    comparability: z.enum(["comparable", "conditional", "not_comparable"]),
 70	    anchor: anchorSchema,
 71	  }).strict(),
 72	  alternatives: z.array(alternativeSchema).min(1),
 73	  /** The declared discriminator; without one there is no ranking. all_in_cost ranks only the new debts among themselves. */
 74	  ranking: z.object({discriminator: z.enum(["headroom", "all_in_cost", "peak_concentration", "peak_amount", "net_debt"]), rationale: nonEmpty}).strict().nullable().default(null),
 75	  wallThreshold: z.object({share: nonNegative, policyKey: nonEmpty, policyVersion: nonEmpty}).strict(),
 76	}).strict().superRefine((input, context) => {
 77	  if (!UNIT_WORDS[input.unit].test(input.unitAnchor.note)) context.addIssue({code: "custom", path: ["unitAnchor"], message: `the unit anchor's note does not name the unit ${input.unit}; a relabelled scale is refused`});
 78	  if (input.covenant.measurement.nextDate <= input.referenceDate) context.addIssue({code: "custom", path: ["covenant", "measurement"], message: "the next measurement date must follow the reference date"});
 79	  if (new Decimal(input.wallThreshold.share).gt(1)) context.addIssue({code: "custom", path: ["wallThreshold", "share"], message: "a wall threshold is a share of gross debt between 0 and 1"});
 80	  if (input.before.ltmEbitda) {
 81	    const start = new Date(`${input.before.ltmEbitda.periodStart}T00:00:00Z`); start.setUTCMonth(start.getUTCMonth() + 12);
 82	    if (start.toISOString().slice(0, 10) !== input.before.ltmEbitda.periodEnd) context.addIssue({code: "custom", path: ["before", "ltmEbitda"], message: `the EBITDA covers ${input.before.ltmEbitda.periodStart} to ${input.before.ltmEbitda.periodEnd}, not twelve months; an annualized shorter period is not an LTM figure`});
 83	    if (input.before.ltmEbitda.periodEnd > input.referenceDate) context.addIssue({code: "custom", path: ["before", "ltmEbitda"], message: "the EBITDA period ends after the reference date"});
 84	  }
 85	  const periods = new Set<string>();
 86	  const sorted = [...input.before.schedule].sort(scheduleOrder);
 87	  sorted.forEach((entry, index) => {
 88	    if (periods.has(entry.period)) context.addIssue({code: "custom", path: ["before", "schedule", index], message: `duplicate period ${entry.period}`});
 89	    periods.add(entry.period);
 90	    if (entry.endsAt !== null && entry.endsAt <= input.referenceDate) context.addIssue({code: "custom", path: ["before", "schedule", index], message: `period ${entry.period} ends on or before the reference date`});
 91	    if (entry.kind === "maturity" && entry.amount.startsWith("-")) context.addIssue({code: "custom", path: ["before", "schedule", index], message: `period ${entry.period} carries a negative amount; only an adjustment row may`});
 92	    if (entry.kind === "adjustment" && entry.endsAt !== null) context.addIssue({code: "custom", path: ["before", "schedule", index], message: `adjustment ${entry.period} belongs to no period and cannot end on a date`});
 93	  });
 94	  if (sorted.filter((entry) => entry.endsAt === null && entry.kind === "maturity").length > 1) context.addIssue({code: "custom", path: ["before", "schedule"], message: "at most one open-ended bucket"});
 95	  const ids = new Set<string>();
 96	  input.alternatives.forEach((alternative, index) => {
 97	    if (ids.has(alternative.id)) context.addIssue({code: "custom", path: ["alternatives", index], message: `duplicate alternative ${alternative.id}`});
 98	    ids.add(alternative.id);
 99	    const series = new Set<string>();
100	    alternative.retired.forEach((entry, position) => {
101	      if (series.has(entry.seriesId)) context.addIssue({code: "custom", path: ["alternatives", index, "retired", position], message: `${alternative.id}: series ${entry.seriesId} retired twice`});
102	      series.add(entry.seriesId);
103	      if (!periods.has(entry.maturityPeriod) || input.before.schedule.find((row) => row.period === entry.maturityPeriod)?.kind === "adjustment") context.addIssue({code: "custom", path: ["alternatives", index, "retired", position], message: `${alternative.id}: ${entry.seriesId} matures in ${entry.maturityPeriod}, which is not a period of the schedule`});
104	    });
105	    if (alternative.newDebt && alternative.newDebt.disbursementDate < input.referenceDate) context.addIssue({code: "custom", path: ["alternatives", index, "newDebt", "disbursementDate"], message: `${alternative.id}: the new debt is disbursed before the reference date`});
106	    if (alternative.newDebt && alternative.newDebt.graceMonths >= alternative.newDebt.termMonths) context.addIssue({code: "custom", path: ["alternatives", index, "newDebt", "graceMonths"], message: `${alternative.id}: grace must be shorter than the term`});
107	  });
108	});
109	export type BeforeAfterInput = z.input<typeof beforeAfterInputSchema>;
110	
111	type Calculation = {id: string; alternative: string; formula: string; operands: Record<string, string>; result: string; unit: string};
112	type Snapshot = {
113	  gross_debt: string; deductible_cash: string; net_debt: string; contractual_net_debt: string;
114	  leverage: {value: string; ebitda_definition: string; ebitda_basis: string} | null;
115	  headroom: {absolute: string; within_limit: boolean; reading: "interim" | "measurement_date"; note: string} | null;
116	  peak: {period: string; amount: string; share_of_gross: string} | null;
117	  cost: {value: string; basis: string; comparable_with_new_debt: boolean};
118	  anchors: Record<string, Anchor>;
119	};
120	
121	export type BeforeAfterOutput = {
122	  schema_version: "method.compare-refinancing-before-after.v5";
123	  reference_date: string;
124	  unit: string;
125	  state: "compared" | "blocked";
126	  block_reasons: string[];
127	  wall_threshold: {share: string; policyKey: string; policyVersion: string};
128	  /** Rows of the ledger's schedule that belong to no period (transaction costs); they reconcile the schedule to the gross debt and never enter the concentration. */
129	  schedule_adjustments: Array<{id: string; amount: string}>;
130	  before: Snapshot;
131	  alternatives: Array<{
132	    id: string; label: string; state: "compared" | "blocked"; block_reasons: string[];
133	    after: Snapshot | null;
134	    effective_date: string | null;
135	    temporal_note: string | null;
136	    exit_cost: {value: string; anchors: Anchor[]} | null;
137	    concentration: Array<{period: string; existing: string; proposed: string; consolidated: string; share_of_gross: string; is_wall: boolean; principal_coverage: string | null}> | null;
138	    new_debt_service: {peak_debt_service: string; total_interest: string; weighted_average_life_months: string; all_in_cost: string | null; anchor: Anchor} | null;
139	    uncovered_terms: Array<{id: string; state: "insufficient_evidence"; reason: string}>;
140	  }>;
141	  /** `value` is the economic figure of the discriminator (a share, a cost, an amount); `score` is the internal ordering key (higher is better). */
142	  ranking: {discriminator: string; rationale: string; order: Array<{id: string; value: string; score: string; reason: string}>} | null;
143	  unsupported: string[];
144	  trace: {calculations: Calculation[]; inputFingerprint: string; outputFingerprint: string};
145	};
146	
147	const d = (value: Decimal.Value) => new Decimal(value);
148	const out = (value: Decimal) => value.toDecimalPlaces(8).toFixed();
149	const stableStringify = (value: unknown): string => JSON.stringify(value, (_key, inner: unknown) => (inner && typeof inner === "object" && !Array.isArray(inner) ? Object.fromEntries(Object.entries(inner as Record<string, unknown>).sort(([a], [b]) => compare(a, b))) : inner));
150	const fingerprint = (value: unknown) => createHash("sha256").update(stableStringify(value)).digest("hex");
151	const addMonths = (isoDate: string, months: number) => { const date = new Date(`${isoDate}T00:00:00Z`); date.setUTCMonth(date.getUTCMonth() + months); return date.toISOString().slice(0, 10); };
152	
153	const scheduleOrder = (a: {period: string; endsAt: string | null; kind: string}, b: {period: string; endsAt: string | null; kind: string}) => (a.kind !== b.kind ? (a.kind === "adjustment" ? 1 : -1) : a.endsAt === null && b.endsAt === null ? compare(a.period, b.period) : a.endsAt === null ? 1 : b.endsAt === null ? -1 : compare(a.endsAt, b.endsAt) || compare(a.period, b.period));
154	function canonical(input: z.infer<typeof beforeAfterInputSchema>) {
155	  return {
156	    ...input,
157	    before: {...input.before, schedule: [...input.before.schedule].sort(scheduleOrder)},
158	    alternatives: [...input.alternatives].sort((a, b) => compare(a.id, b.id)).map((alternative) => ({...alternative, retired: [...alternative.retired].sort((a, b) => compare(a.seriesId, b.seriesId)), uncoveredTerms: [...alternative.uncoveredTerms].sort(compare)})),
159	  };
160	}
161	
162	export function compareRefinancingBeforeAfter(raw: BeforeAfterInput): BeforeAfterOutput {
163	  const input = canonical(beforeAfterInputSchema.parse(raw));
164	  const calculations: Calculation[] = [];
165	  const record = (calculation: Omit<Calculation, "unit">, unit: string = input.unit) => calculations.push({...calculation, unit});
166	  const unsupported: string[] = [];
167	  const blockReasons: string[] = [];
168	  const threshold = d(input.wallThreshold.share);
169	  const tierApplicable = input.covenant.tier === null || input.covenant.tier.applicability === "applicable";
170	  const canMeasureHeadroom = input.covenant.state === "resolved" && input.covenant.comparability === "comparable" && tierApplicable;
171	  if (!canMeasureHeadroom) unsupported.push(`headroom is not measured: covenant limit ${input.covenant.state}, comparability ${input.covenant.comparability}${input.covenant.tier && input.covenant.tier.applicability !== "applicable" ? `, tier ${input.covenant.tier.applicability} (${input.covenant.tier.condition})` : ""}`);
172	  const ebitda = input.before.ltmEbitda;
173	  if (!ebitda) unsupported.push("leverage is not measured: no EBITDA with a definition in the base");
174	  else if (d(ebitda.value).lte(0)) unsupported.push("leverage is not measured: the EBITDA in the base is zero or negative");
175	  if (!input.before.cfadsByPeriod) unsupported.push("principal cover per period is not measured: no cash generation per period in the base");
176	  const scheduleTotal = input.before.schedule.reduce((sum, entry) => sum.plus(entry.amount), d(0));
177	  if (!scheduleTotal.eq(input.before.grossDebt.value)) blockReasons.push(`the schedule sums to ${out(scheduleTotal)} and the gross debt is ${input.before.grossDebt.value}; the ledger did not reconcile them`);
178	  const maturities = input.before.schedule.filter((entry) => entry.kind === "maturity");
179	  const adjustments = input.before.schedule.filter((entry) => entry.kind === "adjustment");
180	  const periodOf = (date: string): string | null => {
181	    const dated = maturities.filter((entry) => entry.endsAt !== null);
182	    const hit = dated.find((entry) => date <= entry.endsAt!);
183	    if (hit) return hit.period;
184	    const open = maturities.find((entry) => entry.endsAt === null);
185	    return open ? open.period : null;
186	  };
187	
188	  const snapshot = (label: string, grossDebt: Decimal, cash: Decimal, cost: Snapshot["cost"], consolidated: Record<string, Decimal.Value>, anchors: Record<string, Anchor>): Snapshot => {
189	    const views = aggregateDebtViews({rows: [{id: "gross_debt", principal: out(grossDebt), covenantIncluded: true}, {id: "derivative_liabilities", principal: input.before.derivativeLiabilities.value, covenantIncluded: true}], cash: cash.plus(input.before.derivativeAssets.value)});
190	    const contractual = d(views.netFinancialDebt);
191	    record({id: "financial.debt_views:contractual", alternative: label, formula: "grossDebt + derivativeLiabilities - derivativeAssets - deductibleCash", operands: {grossDebt: out(grossDebt), derivativeLiabilities: input.before.derivativeLiabilities.value, derivativeAssets: input.before.derivativeAssets.value, deductibleCash: out(cash)}, result: out(contractual)});
192	    let leverage: Snapshot["leverage"] = null;
193	    if (ebitda && d(ebitda.value).gt(0)) {
194	      const result = calculateLeverage(out(contractual), ebitda.value);
195	      record({id: "financial.net_leverage", alternative: label, formula: "contractualNetDebt / ltmEbitda", operands: {contractualNetDebt: out(contractual), ltmEbitda: ebitda.value, ebitdaBasis: ebitda.basis}, result: result.value}, "x");
196	      leverage = {value: result.value, ebitda_definition: ebitda.definitionKey, ebitda_basis: ebitda.basis};
197	    }
198	    let headroom: Snapshot["headroom"] = null;
199	    if (leverage && canMeasureHeadroom) {
200	      const result = calculateCovenantHeadroom({actual: leverage.value, limit: input.covenant.limit, direction: input.covenant.direction});
201	      record({id: "structure.covenant_headroom", alternative: label, formula: input.covenant.direction === "maximum" ? "limit - actual" : "actual - limit", operands: {actual: leverage.value, limit: input.covenant.limit}, result: result.absolute}, "x");
202	      const onDate = input.covenant.measurement.nextDate === input.referenceDate;
203	      headroom = {absolute: result.absolute, within_limit: result.passes, reading: onDate ? "measurement_date" : "interim", note: onDate ? `measured on the measurement date of ${input.covenant.instrument}` : `interim reading at ${input.referenceDate}; ${input.covenant.instrument} measures ${input.covenant.measurement.frequency}ly, next on ${input.covenant.measurement.nextDate}; neither a breach nor a compliance`};
204	    }
205	    const concentration = maturityConcentration({existing: consolidated, proposed: {}});
206	    const peak = concentration.peak && grossDebt.gt(0) ? {period: concentration.peak.period, amount: concentration.peak.consolidated, share_of_gross: out(d(concentration.peak.consolidated).div(grossDebt))} : null;
207	    if (peak) record({id: "structure.maturity_concentration:peak", alternative: label, formula: "peak / grossDebt", operands: {peak: peak.amount, grossDebt: out(grossDebt)}, result: peak.share_of_gross}, "x");
208	    return {gross_debt: out(grossDebt), deductible_cash: out(cash), net_debt: out(grossDebt.minus(cash)), contractual_net_debt: out(contractual), leverage, headroom, peak, cost, anchors};
209	  };
210	
211	  const beforeSchedule = Object.fromEntries(maturities.map((entry) => [entry.period, entry.amount]));
212	  const before = snapshot("before", d(input.before.grossDebt.value), d(input.before.unrestrictedCash.value), {value: input.before.costOfExistingDebt.weightedAverageRate, basis: input.before.costOfExistingDebt.basis, comparable_with_new_debt: false}, beforeSchedule, {grossDebt: input.before.grossDebt.anchor, unrestrictedCash: input.before.unrestrictedCash.anchor, derivativeLiabilities: input.before.derivativeLiabilities.anchor, derivativeAssets: input.before.derivativeAssets.anchor, ...(ebitda ? {ltmEbitda: ebitda.anchor} : {}), cost: input.before.costOfExistingDebt.anchor});
213	
214	  const alternatives = input.alternatives.map((alternative): BeforeAfterOutput["alternatives"][number] => {
215	    const reasons: string[] = [];
216	    const uncovered: BeforeAfterOutput["alternatives"][number]["uncovered_terms"] = alternative.uncoveredTerms.map((term) => ({id: term, state: "insufficient_evidence" as const, reason: `the alternative lacks ${term}; carried as a gap, not filled`}));
217	    const unpriced = alternative.retired.filter((series) => series.exitPremium === null);
218	    if (unpriced.length > 0) reasons.push(`exit cost is not priced for ${unpriced.map((series) => series.seriesId).join(", ")}; the alternative cannot be compared`);
219	    if (reasons.length > 0 || blockReasons.length > 0) return {id: alternative.id, label: alternative.label, state: "blocked", block_reasons: [...blockReasons, ...reasons], after: null, effective_date: null, temporal_note: null, exit_cost: null, concentration: null, new_debt_service: null, uncovered_terms: uncovered};
220	
221	    const retiredPrincipal = alternative.retired.reduce((sum, series) => sum.plus(series.principal.value), d(0));
222	    const exitCost = alternative.retired.reduce((sum, series) => sum.plus(series.exitPremium!.value), d(0));
223	    // Fees the base does not state are unknown, not zero: the position is computed without them and the all-in is not.
224	    const fees = alternative.feesPaidFromCash ? d(alternative.feesPaidFromCash.value) : d(0);
225	    if (!alternative.feesPaidFromCash) uncovered.push({id: "fees_paid_from_cash", state: "insufficient_evidence", reason: "the cash fees of the alternative are not in the base; an explicit zero must be stated; the all-in cost is not computed and the cash after excludes them"});
226	    const newAmount = alternative.newDebt ? d(alternative.newDebt.amount) : d(0);
227	    const upfrontFees = alternative.newDebt ? newAmount.times(alternative.newDebt.upfrontFeeRate) : d(0);
228	    const proForma = calculateProFormaPosition({grossDebt: input.before.grossDebt.value, unrestrictedCash: input.before.unrestrictedCash.value, newDebt: out(newAmount), refinancedDebt: out(retiredPrincipal), feesPaidFromCash: out(fees.plus(exitCost).plus(upfrontFees)), cashContribution: "0"});
229	    record({id: "operation.pro_forma_position", alternative: alternative.id, formula: "grossDebt + newDebt - retired ; cash - exitCost - upfrontFees - feesPaidFromCash", operands: {newDebt: out(newAmount), refinancedDebt: out(retiredPrincipal), exitCost: out(exitCost), upfrontFees: out(upfrontFees), feesPaidFromCash: out(fees)}, result: proForma.grossDebt});
230	
231	    // Schedule after: retired series leave their periods; the new principal lands in the period that holds its payment date.
232	    const existing: Record<string, Decimal> = Object.fromEntries(maturities.map((entry) => [entry.period, d(entry.amount)]));
233	    for (const series of alternative.retired) {
234	      if (existing[series.maturityPeriod]!.lt(series.principal.value)) reasons.push(`${series.seriesId}: the period ${series.maturityPeriod} holds ${out(existing[series.maturityPeriod]!)} and cannot lose ${series.principal.value}`);
235	      existing[series.maturityPeriod] = existing[series.maturityPeriod]!.minus(series.principal.value);
236	    }
237	    if (reasons.length > 0) return {id: alternative.id, label: alternative.label, state: "blocked", block_reasons: reasons, after: null, effective_date: null, temporal_note: null, exit_cost: null, concentration: null, new_debt_service: null, uncovered_terms: uncovered};
238	    const proposed: Record<string, Decimal> = {};
239	    let newDebtService: BeforeAfterOutput["alternatives"][number]["new_debt_service"] = null;
240	    let cost: Snapshot["cost"] = {value: input.before.costOfExistingDebt.weightedAverageRate, basis: `${input.before.costOfExistingDebt.basis}; no new debt`, comparable_with_new_debt: false};
241	    if (alternative.newDebt) {
242	      const schedule = buildDebtServiceSchedule({amount: alternative.newDebt.amount, annualRate: alternative.newDebt.annualRate, rateConvention: "effective_annual", termMonths: alternative.newDebt.termMonths, graceMonths: alternative.newDebt.graceMonths, graceInterest: "paid", format: alternative.newDebt.format});
