318	    else if (scored.some((entry) => entry.score === null)) unsupported.push(input.ranking.discriminator === "all_in_cost" ? "ranking by all_in_cost needs a new debt in every compared alternative; the cost of existing debt is another basis" : `ranking by ${input.ranking.discriminator} needs a value every compared alternative lacks`);
319	    else {
320	      const sorted = scored.sort((a, b) => b.score!.comparedTo(a.score!) || compare(a.alternative.id, b.alternative.id));
321	      ranking = {discriminator: input.ranking.discriminator, rationale: input.ranking.rationale, order: sorted.map((entry, index) => ({id: entry.alternative.id, value: out(input.ranking!.discriminator === "headroom" ? entry.score! : entry.score!.negated()), score: out(entry.score!), reason: index === 0 ? `best ${input.ranking!.discriminator}` : entry.score!.eq(sorted[0]!.score!) ? `tied with the best on ${input.ranking!.discriminator}; ordered by id, not by merit` : `ranks below by ${input.ranking!.discriminator}`}))};
322	    }
323	  } else unsupported.push("no ranking: the discriminator was not declared");
324	  for (const alternative of alternatives) if (alternative.state === "blocked") unsupported.push(`${alternative.id}: ${alternative.block_reasons.join("; ")}`);
325	
326	  const body = {schema_version: "method.compare-refinancing-before-after.v5" as const, reference_date: input.referenceDate, unit: input.unit, state: blockReasons.length > 0 ? "blocked" as const : "compared" as const, block_reasons: blockReasons, wall_threshold: input.wallThreshold, schedule_adjustments: adjustments.map((entry) => ({id: entry.period, amount: entry.amount})), before, alternatives, ranking, unsupported: [...unsupported].sort(compare)};
327	  const inputFingerprint = fingerprint(input);
328	  return {...body, trace: {calculations, inputFingerprint, outputFingerprint: fingerprint({...body, calculations, inputFingerprint})}};
329	}

